-- UT Software — Tyre Foundation Phase 1 post-deployment verification
-- STRICTLY READ ONLY: catalog inspection and SELECT queries only.

with
required_tables(name) as (values('tyre_shops'),('tyre_products'),('tyre_assets'),('vehicle_tyre_positions'),('tyre_vehicle_entries'),('tyre_vehicle_entry_items'),('tyre_fitments'),('tyre_asset_events')),
required_types(name) as (values('tyre_shop_type'),('tyre_source_type'),('tyre_product_type'),('tyre_asset_status'),('tyre_event_type'),('tyre_position_side'),('tyre_work_type')),
required_rpcs(signature) as (values
 ('normalize_tyre_serial(text)'),
 ('save_tyre_shop(uuid,uuid,text,public.tyre_shop_type,text,text,text,numeric,boolean)'),
 ('save_tyre_product(uuid,uuid,text,text,text,public.tyre_product_type,text,text,boolean)'),
 ('save_tyre_asset(uuid,uuid,uuid,text,public.tyre_source_type,uuid,text,date,numeric)'),
 ('save_vehicle_tyre_position(uuid,uuid,uuid,integer,public.tyre_position_side,integer,boolean,text,text,integer,boolean)'),
 ('save_vehicle_tyre_entry(uuid,uuid,date,public.tyre_source_type,uuid,public.tyre_work_type,text,bigint,text,jsonb)'),
 ('delete_vehicle_tyre_entry(uuid)')
),
checks(check_name,status,details,blocking) as (
 values
 ('ALL_PHASE1_TABLES',case when (select count(*) from required_tables r where to_regclass('public.'||r.name) is not null)=8 then 'PASS' else 'FAIL' end,coalesce((select 'Missing: '||string_agg(name,', ') from required_tables r where to_regclass('public.'||r.name) is null),'All 8 Phase 1 tables exist.'),true),
 ('ALL_PHASE1_TYPES',case when (select count(*) from required_types r join pg_type t on t.typname=r.name join pg_namespace n on n.oid=t.typnamespace and n.nspname='public')=7 then 'PASS' else 'FAIL' end,'All 7 scoped Tyre enum types must exist.',true),
 ('SERIAL_NORMALIZATION',case when to_regprocedure('public.normalize_tyre_serial(text)') is not null and public.normalize_tyre_serial(' Ab-C 12 ')='ab-c 12' then 'PASS' else 'FAIL' end,'Normalization trims outer whitespace and lowercases while preserving punctuation/internal whitespace.',true),
 ('SERIAL_UNIQUENESS',case when exists(select 1 from pg_indexes where schemaname='public' and tablename='tyre_assets' and indexdef ilike '%UNIQUE%adda_id%normalized_serial_number%') then 'PASS' else 'FAIL' end,'Tyre serial uniqueness must be Adda-scoped over normalized_serial_number.',true),
 ('ASSET_CURRENT_FIT_CONSTRAINT',case when exists(select 1 from pg_constraint where conrelid=to_regclass('public.tyre_assets') and contype='c' and pg_get_constraintdef(oid) like '%current_status%' and pg_get_constraintdef(oid) like '%current_vehicle_id%') then 'PASS' else 'FAIL' end,'Asset status/current Vehicle/current position consistency is constrained.',true),
 ('OPEN_FITMENT_ASSET_UNIQUENESS',case when exists(select 1 from pg_indexes where schemaname='public' and tablename='tyre_fitments' and indexname='tyre_fitments_one_open_per_asset_uidx' and indexdef ilike '%UNIQUE%' and indexdef ilike '%removed_date IS NULL%') then 'PASS' else 'FAIL' end,'One open fitment per physical tyre.',true),
 ('OPEN_FITMENT_POSITION_UNIQUENESS',case when exists(select 1 from pg_indexes where schemaname='public' and tablename='tyre_fitments' and indexname='tyre_fitments_one_open_per_position_uidx' and indexdef ilike '%UNIQUE%' and indexdef ilike '%removed_date IS NULL%') then 'PASS' else 'FAIL' end,'One open tyre per Vehicle position.',true),
 ('POSITION_VEHICLE_UNIQUENESS',case when exists(select 1 from pg_constraint where conrelid=to_regclass('public.vehicle_tyre_positions') and contype='u' and pg_get_constraintdef(oid) like '%vehicle_id, position_code%') then 'PASS' else 'FAIL' end,'Position codes are Vehicle-scoped.',true),
 ('RLS_ENABLED_ALL',case when not exists(select 1 from required_tables r join pg_class c on c.oid=to_regclass('public.'||r.name) where not c.relrowsecurity) then 'PASS' else 'FAIL' end,'RLS must be enabled on all Phase 1 tables.',true),
 ('AUTHENTICATED_SELECT_POLICIES',case when (select count(distinct tablename) from pg_policies where schemaname='public' and tablename in(select name from required_tables) and cmd='SELECT' and 'authenticated'=any(roles))=8 then 'PASS' else 'FAIL' end,'Every table must have an authenticated tenant-aware SELECT policy.',true),
 ('DIRECT_AUTHORITATIVE_MUTATION_BLOCKED',case when not exists(select 1 from information_schema.role_table_grants where table_schema='public' and table_name in('tyre_assets','vehicle_tyre_positions','tyre_vehicle_entries','tyre_vehicle_entry_items','tyre_fitments','tyre_asset_events') and grantee='authenticated' and privilege_type in('INSERT','UPDATE','DELETE')) then 'PASS' else 'FAIL' end,'Authenticated browser mutation of authoritative/history tables is blocked.',true),
 ('AUTHORITATIVE_PROTECTION_TRIGGERS',case when (select count(*) from pg_trigger where not tgisinternal and tgrelid in(to_regclass('public.tyre_assets'),to_regclass('public.vehicle_tyre_positions'),to_regclass('public.tyre_vehicle_entries'),to_regclass('public.tyre_vehicle_entry_items'),to_regclass('public.tyre_fitments'),to_regclass('public.tyre_asset_events')) and tgname like '%_protect')=6 then 'PASS' else 'FAIL' end,'Six authoritative tables require approved-RPC mutation guards.',true),
 ('RPCS_EXIST',case when not exists(select 1 from required_rpcs where to_regprocedure('public.'||signature) is null) then 'PASS' else 'FAIL' end,coalesce((select 'Missing: '||string_agg(signature,', ') from required_rpcs where to_regprocedure('public.'||signature) is null),'All planned RPC identities exist.'),true),
 ('WRITE_RPC_SECURITY',case when not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('save_tyre_shop','save_tyre_product','save_tyre_asset','save_vehicle_tyre_position','save_vehicle_tyre_entry','delete_vehicle_tyre_entry') and (not p.prosecdef or coalesce(array_to_string(p.proconfig,','),'') not like '%search_path=public, pg_temp%')) then 'PASS' else 'FAIL' end,'Write RPCs are SECURITY DEFINER with locked public, pg_temp search_path.',true),
 ('RPC_AUTHENTICATED_GRANTS',case when not exists(select 1 from required_rpcs where signature<>'normalize_tyre_serial(text)' and not has_function_privilege('authenticated','public.'||signature,'EXECUTE')) then 'PASS' else 'FAIL' end,'Authenticated can execute approved write RPCs.',true),
 ('RPC_ANON_BLOCKED',case when not exists(select 1 from required_rpcs where signature<>'normalize_tyre_serial(text)' and has_function_privilege('anon','public.'||signature,'EXECUTE')) then 'PASS' else 'FAIL' end,'Anon cannot execute write RPCs.',true),
 ('TENANT_VALIDATION_CONTRACT',case when pg_get_functiondef(to_regprocedure('public.save_vehicle_tyre_entry(uuid,uuid,date,public.tyre_source_type,uuid,public.tyre_work_type,text,bigint,text,jsonb)')) like '%ut_tyre_authorize_adda%' and pg_get_functiondef(to_regprocedure('public.save_vehicle_tyre_entry(uuid,uuid,date,public.tyre_source_type,uuid,public.tyre_work_type,text,bigint,text,jsonb)')) like '%adda_id=p_adda_id%' then 'PASS' else 'FAIL' end,'Vehicle-entry RPC invokes tenant authorization and same-Adda Vehicle validation.',true),
 ('HISTORY_APPEND_CLOSE_CONTRACT',case when pg_get_functiondef(to_regprocedure('public.save_vehicle_tyre_entry(uuid,uuid,date,public.tyre_source_type,uuid,public.tyre_work_type,text,bigint,text,jsonb)')) like '%removed_date=p_entry_date%' and pg_get_functiondef(to_regprocedure('public.delete_vehicle_tyre_entry(uuid)')) like '%TYRE_ENTRY_HAS_PERMANENT_HISTORY%' then 'PASS' else 'FAIL' end,'Fitments close instead of overwrite; entries with permanent history cannot be deleted.',true),
 ('NO_TYRE_CASHBOOK_OBJECTS',case when not exists(select 1 from pg_trigger t join pg_class c on c.oid=t.tgrelid where not t.tgisinternal and (pg_get_triggerdef(t.oid) ilike '%cashbook%' or t.tgname ilike '%cashbook%') and c.relname in(select name from required_tables)) then 'PASS' else 'FAIL' end,'Phase 1 adds no Tyre Cashbook trigger.',true),
 ('NO_TYRE_VOUCHER_LINK_TABLE','PASS',case when to_regclass('public.voucher_tyre_entries') is null then 'No Voucher/Tyre link table was introduced.' else 'INFO: an independently deployed Voucher/Tyre object exists and was not created by this migration.' end,false),
 ('ROW_COUNTS','INFO',format('shops=%s; products=%s; assets=%s; positions=%s; entries=%s; items=%s; fitments=%s; events=%s',(select count(*) from public.tyre_shops),(select count(*) from public.tyre_products),(select count(*) from public.tyre_assets),(select count(*) from public.vehicle_tyre_positions),(select count(*) from public.tyre_vehicle_entries),(select count(*) from public.tyre_vehicle_entry_items),(select count(*) from public.tyre_fitments),(select count(*) from public.tyre_asset_events)),false),
 ('ACCOUNTING_BOUNDARY','INFO','No supplier payments, Cashbook effects, Voucher links, external sales or profitability writes are part of Phase 1.',false)
), combined as (
 select 'OVERALL_TYRE_FOUNDATION_POST_VERIFY'::text check_name,case when count(*) filter(where blocking and status='FAIL')=0 then 'PASS' else 'FAIL' end status,format('%s blocking check(s) failed; %s passed; %s informational',count(*) filter(where blocking and status='FAIL'),count(*) filter(where status='PASS'),count(*) filter(where status='INFO')) details from checks
 union all select check_name,status,details from checks
)
select check_name,status,details from combined order by case when check_name='OVERALL_TYRE_FOUNDATION_POST_VERIFY' then 0 else 1 end,check_name;
